				gotoLabel = opcode.label();
			} else if (opcode.id() == OpcodeKey::RET || opcode.id() == OpcodeKey::RETTO) {
				++opcodeID;
				break;
			}
		}
		++opcodeID;
	}

	Script s(_opcodes.mid(opcodeID));
