//				}
				if (palette != nullptr) {
					bits[pos + y * 256 + x] = palette->color(indexOrRgb);
				} else {
					bits[pos + y * 256 + x] = qRgb(indexOrRgb, indexOrRgb, indexOrRgb);
				}

				if (++x >= tile.size) {
					x = 0;
					++y;
				}
			}
		}
	}

	return img;
}

