	const QList<FieldModelColorDir> &lightColors = model.lightColors();
	modelHeader.colorADir1 = lightColors.at(0).dirA;
	modelHeader.colorADir2 = lightColors.at(0).dirB;
	modelHeader.colorADir3 = lightColors.at(0).dirC;
