{
	return id() == OpcodeKey::JMPFL
	        || id() == OpcodeKey::JMPBL
	        || id() == OpcodeKey::IFUBL
	        || id() == OpcodeKey::IFSWL
	        || id() == OpcodeKey::IFUWL
	        || id() == OpcodeKey::Unused1B;
