	switch (id()) {
		CaseOpcodeIf(IFUB, FF7Var::Byte);
		CaseOpcodeIf(IFUBL, FF7Var::Byte);
		CaseOpcodeIf(IFSW, FF7Var::SignedWord);
		CaseOpcodeIf(IFSWL, FF7Var::SignedWord);
		CaseOpcodeIf(IFUW, FF7Var::Word);
		CaseOpcodeIf(IFUWL, FF7Var::Word);
