void Section1File::listModelPositions(QMultiMap<int, FF7Position> &positions) const
{
	int modelId = 0;
	for (const GrpScript &group : _grpScripts) {
		if (group.type() == GrpScript::Model) {
			QList<FF7Position> pos;
			group.listModelPositions(pos);
