void PaletteIOPC::setDeviceAlpha(QIODevice *device)
{
	_deviceAlpha = device;
}

QIODevice *PaletteIOPC::deviceAlpha() const
{
	return _deviceAlpha;
}

bool PaletteIOPC::canReadAlpha() const
{
	if (_deviceAlpha) {
		if (!_deviceAlpha->isOpen()) {
			return _deviceAlpha->open(QIODevice::ReadOnly);
		}
		return _deviceAlpha->isReadable();
	}
	return false;
}

bool PaletteIOPC::canWriteAlpha() const
{

if (!_deviceAlpha->isOpen()) {
			return _deviceAlpha->open(QIODevice::ReadOnly);
		}
		return _deviceAlpha->isReadable();
	}
	return false;
}

bool PaletteIOPC::canWriteAlpha() const
{
	if (_deviceAlpha) {
		if (!_deviceAlpha->isOpen()) {
			return _deviceAlpha->open(QIODevice::WriteOnly);
		}
		return _deviceAlpha->isWritable();
	}
	return false;
}

bool PaletteIOPC::readAfter(Palettes &palettes) const
{
	if (!canReadAlpha()) {
		return false;
	}

	QByteArray palFlags = deviceAlpha()->read(PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT);

	if (palFlags.size() < PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT) {
		return false;
	}

	quint8 palId = 0;

	for (Palette *palette : palettes) {
		if (palId >= PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT) {
			break;
		}

		static_cast<PalettePC *>(palette)->setTransparency(palFlags.at(palId));

		++palId;
	}

	return true;
}

bool PaletteIOPC::writeAfter(const Palettes &palettes) const
{
	if (!canWriteAlpha()) {
		return false;
	}

	quint8 palId = 0;

	for (const Palette *palette : palettes) {
		if (palId >= PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT) {
			break;
		}

		quint8 trans = static_cast<const PalettePC *>(palette)->transparency();

}

	quint8 palId = 0;

	for (const Palette *palette : palettes) {
		if (palId >= PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT) {
			break;
		}

		quint8 trans = static_cast<const PalettePC *>(palette)->transparency();
		if (deviceAlpha()->write((char *)&trans, 1) != 1) {
			return false;
		}

		++palId;
	}

	if (palId < PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT) {
		return deviceAlpha()->write(QByteArray(PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT - palId, '\0')) == PALETTE_PC_MAX_FIRST_COLOR_TRANS_COUNT - palId;
	}

	return true;
}

