bool TutFileStandard::isTut(qsizetype tutID) const
{
	return !isAkao(tutID);
}

bool TutFileStandard::isAkao(qsizetype tutID) const
{
	return data(tutID).startsWith("AKAO")/* || !field()->scriptsAndTexts()->listUsedTuts().contains(tutID) */;
}

bool TutFileStandard::isBroken(int tutID) const
{
	if (isAkao(tutID)) {
		return false;
	}
	const QByteArray &d = data(tutID);
	if (!d.isEmpty()) {
		quint8 firstChar = quint8(d.at(0));
		return firstChar > 0x12 && firstChar < 0xFF;
	}
	return false;
}

bool TutFileStandard::canBeRepaired(int tutID) const
{
	const QByteArray &d = data(tutID);
	return d.startsWith("KAO") || d.startsWith("AO");
}

bool TutFileStandard::repair(int tutID)
{
	const QByteArray &d = data(tutID);
	if (d.startsWith("KAO")) {
		setData(tutID, QByteArray("A", 1).append(d));
		return true;
	}
	if (d.startsWith("AO")) {
		setData(tutID, QByteArray("AK", 2).append(d));
		return true;
	}
	return false;
}

QString TutFileStandard::parseScripts(int tutID, bool *warnings) const
{
	QString ret;

	if (!isTut(tutID)) {
		const QByteArray &tuto = data(tutID);
		const char *constTuto = tuto.constData();

		quint16 id, length, firstPos;

QString TutFileStandard::parseScripts(int tutID, bool *warnings) const
{
	QString ret;

	if (!isTut(tutID)) {
		const QByteArray &tuto = data(tutID);
		const char *constTuto = tuto.constData();

		quint16 id, length, firstPos;
		if (tuto.size() < 6) {
			if (warnings) {
				*warnings = true;
			}
			return QObject::tr("Error");
		}
		memcpy(&id, constTuto + 4, 2);

		ret.append(QObject::tr("totalLength=%1\nid=%2\n").arg(tuto.size()).arg(id));

		if (tuto.size() < 8) {
			return ret;
		}
		memcpy(&length, constTuto + 6, 2);

		ret.append(QObject::tr("length=%1\n").arg(length));

		if (tuto.size() < 22) {
			return ret;
		}
		memcpy(&firstPos, constTuto + 20, 2);

		ret.append(QObject::tr("ChannelCount=%1\n").arg(firstPos/2 + 1));
		ret.append(QString::fromLatin1(tuto.mid(8, 8).toHex()));
		ret.append("\n");
		ret.append(QString::fromLatin1(tuto.mid(16, 4).toHex()));
		ret.append("\n");
	} else {
		ret = TutFile::parseScripts(tutID, warnings);
	}

	return ret;
}

int TutFileStandard::akaoID(int tutID) const
{
	if (isTut(tutID))	return -1;

	const QByteArray &data = this->data(tutID);
	if (data.size() < 6)		return -1;
	quint16 id;
	memcpy(&id, data.constData() + 4, 2);

	return id;
}

void TutFileStandard::setAkaoID(int tutID, quint16 akaoID)
{
	if (isTut(tutID))	return;

quint16 id;
	memcpy(&id, data.constData() + 4, 2);

	return id;
}

void TutFileStandard::setAkaoID(int tutID, quint16 akaoID)
{
	if (isTut(tutID))	return;

	dataRef(tutID).replace(4, 2, (char *)&akaoID, 2);
	setModified(true);
}

