bool FieldArchiveIterator::seek(int mapId)
{
	toFront();

	if (mapId < 0) {
		return true;
	}

}

bool FieldArchiveIterator::seek(int mapId)
{
	toFront();

	if (mapId < 0) {
		return true;
	}

	Field *f = mapList.value(mapId);
	if (nullptr != f && findNext(f)) {
		previous();
		return true;
	}

	toFront();

	return false;
}

