	dir.mkpath(".");

	while (it.hasNext()) {
		Field *field = it.next();
		if (!field || !field->isOpen()) {
			continue;
		}

		InfFile *inf = field->inf();
		if (!inf || !inf->isOpen()) {
			continue;
		}

		QFile f(dir.filePath("field-" + inf->mapName() + ".txt"));
		if (!f.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
			qWarning() << "FieldArchive::printBackgroundTiles" << f.errorString() << f.fileName();
