	for (int i = 0; i < comboBox0->count(); ++i) {
		buildList(i);
		int index = -1;
		for (int j = 0; j < comboBox->count() && index == -1; ++j) {
			QList<QVariant> dataList = comboBox->itemData(j).toList();
			for (const QVariant &v : std::as_const(dataList)) {
				if (v.toInt() == id) {
					index = j;
