QVariant LgpItemModel::data(const QModelIndex &index, int role) const
{
	if (!index.isValid()) {
		return QVariant();
	}

	LgpItem *lgpItem = item(index);
	if (!lgpItem) {
		return QVariant();
	}

	switch (role) {
	case Qt::EditRole:
	case Qt::DisplayRole:
		switch (index.column()) {
		case 0:		return lgpItem->name();
		case 1:
			if (lgpItem->isDirectory()) {

return QVariant();
	}

	switch (role) {
	case Qt::EditRole:
	case Qt::DisplayRole:
		switch (index.column()) {
		case 0:		return lgpItem->name();
		case 1:
			if (lgpItem->isDirectory()) {
				return QString();
			} else {
				qint64 fileSize = static_cast<LgpFileItem *>(lgpItem)->fileSize();
				return fileSize < 0 ? tr("?") : QString::number(fileSize);
			}
		default:	break;
		}
		break;
	case Qt::DecorationRole:
		if (index.column() == 0) {
			if (lgpItem->isDirectory()) {
				return directoryIcon;
			} else {
				if (static_cast<LgpFileItem *>(lgpItem)->icon().isNull()) {
					QString fname = lgpItem->name();
					for(const auto & ext : _textureTypes) {
						if (fname.endsWith(ext, Qt::CaseInsensitive)) {
							return textureIcon;
						}
					}
					return fileIcon;
				} else {
					return static_cast<LgpFileItem *>(lgpItem)->icon();
				}
			}
		}
		break;
	case Qt::TextAlignmentRole:
		if (index.column() == 1) {
			return Qt::AlignRight;
		}
		break;
	}

	return QVariant();
}

