void QColorPicker::setCol(int h, int s)
{
	int nhue = std::min(std::max(0, h), 359);
	int nsat = std::min(std::max(0, s), 255);

	if (nhue == hue && nsat == sat) {
		return;
	}

	QRect r(colPt(), QSize(20, 20));
	hue = nhue;
	sat = nsat;
	r = r.united(QRect(colPt(), QSize(20, 20)));
	r.translate(contentsRect().x() - 9, contentsRect().y() - 9);
	repaint(r);
}

void QColorPicker::mouseMoveEvent(QMouseEvent *m)
{
	QPoint p = m->pos() - contentsRect().topLeft();
	setCol(p);

	emit newCol(hue, sat);

r.translate(contentsRect().x() - 9, contentsRect().y() - 9);
	repaint(r);
}

void QColorPicker::mouseMoveEvent(QMouseEvent *m)
{
	QPoint p = m->pos() - contentsRect().topLeft();
	setCol(p);

	emit newCol(hue, sat);
}

void QColorPicker::mousePressEvent(QMouseEvent *m)
{
	QPoint p = m->pos() - contentsRect().topLeft();
	setCol(p);

	emit newCol(hue, sat);
}

void QColorPicker::paintEvent(QPaintEvent *event)
{
	Q_UNUSED(event)

	QPainter p(this);
	drawFrame(&p);
	QRect r = contentsRect();
	if (isEnabled()) {
		p.drawPixmap(r.topLeft(), pix);
		QPoint pt = colPt() + r.topLeft();
		p.setPen(Qt::black);
		p.fillRect(pt.x() - 9, pt.y(), 20, 2, Qt::black);
		p.fillRect(pt.x(), pt.y() - 9, 2, 20, Qt::black);
	} else {
		p.drawImage(r.topLeft(), pix.toImage().convertToFormat(QImage::Format_Grayscale8));
	}
}

void QColorPicker::resizeEvent(QResizeEvent *ev)
{
	QFrame::resizeEvent(ev);

	int w = width() - frameWidth() * 2;
	int h = height() - frameWidth() * 2;
	QImage img(w, h, QImage::Format_RGB32);
	int x, y;
	uint *pixel = (uint *) img.scanLine(0);

	for (y = 0; y < h; y++) {
		const uint *end = pixel + w;
		x = 0;
		while (pixel < end) {
			QPoint p(x, y);
			QColor c;
			c.setHsv(huePt(p), satPt(p), 200);
			*pixel = PsColor::fromPsColor(PsColor::toPsColor(c.rgb()));
			++pixel;
			++x;
		}
	}

x = 0;
		while (pixel < end) {
			QPoint p(x, y);
			QColor c;
			c.setHsv(huePt(p), satPt(p), 200);
			*pixel = PsColor::fromPsColor(PsColor::toPsColor(c.rgb()));
			++pixel;
			++x;
		}
	}

	pix = QPixmap::fromImage(img);
}

