void WalkmeshManager::editRange(int id, int v)
{
	if (infFile->isOpen()) {
		Range old = infFile->cameraRange();
		qint16 oldv = 0;

		switch (id) {
		case 0:
			oldv = old.top;
			break;
		case 1:
			oldv = old.bottom;
			break;
		case 2:
			oldv = old.right;
			break;
		case 3:
			oldv = old.left;
			break;
		}

		if (oldv != v) {
			switch (id) {
			case 0:
				old.top = qint16(v);
				break;
			case 1:
				old.bottom = qint16(v);
				break;
			case 2:
				old.right = qint16(v);
				break;
			case 3:
				old.left = qint16(v);
				break;
			}
			infFile->setCameraRange(old);

			emit modified();
		}
	}
}


