		layout->addWidget(_modelPreview, 1, 0);
	}
	layout->setRowStretch(1, 1);
	layout->setContentsMargins(QMargins());

	connect(_models, &QComboBox::currentIndexChanged, this, &ScriptEditorModelPage::updatePreview);
}

