void ScriptEditorBinaryOpPage::changeCurrentOpcode(int index)
{
	OpcodeKey key;

	type1->setEnabled(true);
	type2->setEnabled(true);
	helpWidget->hide();

	switch (index) {
	case 0:
		key = type1->isChecked()
				? OpcodeKey::SETBYTE
				: OpcodeKey::SETWORD;
		break;
	case 1:
		key = type1->isChecked()
				? OpcodeKey::PLUS
				: OpcodeKey::PLUS2;
		break;
	case 2:
		key = type1->isChecked()
				? OpcodeKey::PLUSX
				: OpcodeKey::PLUS2X;
		break;
	case 3:
		key = type1->isChecked()
				? OpcodeKey::MINUS
				: OpcodeKey::MINUS2;
		break;
	case 4:
		key = type1->isChecked()

? OpcodeKey::PLUSX
				: OpcodeKey::PLUS2X;
		break;
	case 3:
		key = type1->isChecked()
