            f.write(QString("(r=%1, g=%2, b=%3, a=%4) ").arg(qRed(color)).arg(qGreen(color)).arg(qBlue(color)).arg(qAlpha(color)).toLatin1());
        f.write("\n");
    }
    for (int i=0 ; i<colorKeyArray.size() ; ++i)
        f.write(QString("%1, ").arg(quint8(colorKeyArray.at(i))).toLatin1());
    f.close();
}

