    static inline quint8 hex2Dec(quint8 hex)
    {
        return 10 * (hex / 16) + hex % 16;
    }
    static inline quint8 dec2Hex(quint8 dec)
    {
        return 16 * (dec / 10) + dec % 10;
    }
