    /* Populate _files */

    int headerEntryID = 0;

    _files->clear(); // This will delete entries

    for (LgpHeaderEntry *entry : tocEntries) {
        if (!_files->addEntry(entry)) {
            qWarning() << "Invalid toc name" << entry->fileName();
            delete entry;
            continue;
        }

        // Set fileDir
        if (hasConflict) {
            const quint16 &conflict = headerConflict.at(headerEntryID);

            if (conflict != 0) {
                const quint16 conflictID = conflict - 1;
                bool resolved = false;

                if (conflictID < conflicts.size()) {
                    const QList<LgpConflictEntry> &conflictEntries = conflicts.at(conflictID);

                    for (const LgpConflictEntry &conflictEntry : conflictEntries) {
                        if (conflictEntry.tocIndex == headerEntryID) {
                            entry->setFileDir(conflictEntry.fileDir);
                            resolved = true;
                            break;
                        }
                    }
                }

                if (!resolved) {
                    qWarning() << "Unresolved conflict for" << entry->fileName();
                }
            }
            ++headerEntryID;
        }
    }

    return true;
}

QByteArray Lgp::readAll(QIODevice *d, bool *ok)
{
    QByteArray result;
    qint64 readBytes = d->size();
    if (readBytes < 0) {
        *ok = false;
        return result;
    }
    // Read it all in one go.
    // If resize fails, don't read anything.
    readBytes -= d->pos();
    result.resize(int(readBytes));
    readBytes = d->read(result.data(), readBytes);

qint64 readBytes = d->size();
    if (readBytes < 0) {
        *ok = false;
        return result;
    }
    // Read it all in one go.
    // If resize fails, don't read anything.
    readBytes -= d->pos();
    result.resize(int(readBytes));
    readBytes = d->read(result.data(), readBytes);

    if (readBytes < 0) {
        if (ok) *ok = false;
        result.clear();
    } else {
        if (ok) *ok = true;
        if (readBytes == 0) {
            result.clear();
        } else {
            result.resize(int(readBytes));
        }
    }
    return result;
}

