            qWarning() << "destination error 1b" << destinationIO->currentSector() << fileLocation << isoFile->name();
        }
        if (destinationIO->pos() != _io.pos()) {
            qWarning() << "destination error 1c" << destinationIO->pos() << _io.pos() << isoFile->name();
        }
#endif

        // On écrit le même nombre de secteurs que le fichier d'origine
        if (!destination->writeFile(isoFile->modifiedFile(), isoFile->sectorCount() + isoFile->paddingAfter(), control)) {
            return false;
        }
        _io.seek(destinationIO->pos());

#ifdef ISOARCHIVE_DEBUG
        if (destinationIO->pos() % SECTOR_SIZE != 0) {
            qWarning() << "destination error 2a" << (destinationIO->pos() % SECTOR_SIZE) << isoFile->name();
        }
        if (destinationIO->currentSector() != _io.currentSector()) {
            qWarning() << "destination error 2b" << destinationIO->currentSector() << _io.currentSector() << isoFile->name();
        }
        if (destinationIO->pos() != _io.pos()) {
            qWarning() << "destination error 2c" << destinationIO->pos() << _io.pos() << isoFile->name();
        }
#endif

        // Envoi de la position courante à l'output
        if (control) {
            control->setObserverValue(int(destinationIO->currentSector()));
        }
    }

    // Données après les fichiers patchés
    if (!copySectors(destinationIO, endOfFilledIso - _io.currentSector(), control)) {
        return false;
    }

#ifdef ISOARCHIVE_DEBUG
    if (destinationIO->pos() % SECTOR_SIZE != 0) {
        qWarning() << "destination error 3a" << (destinationIO->pos() % SECTOR_SIZE);
    }
    if (destinationIO->currentSector() != endOfFilledIso) {
