    }
#endif

    // Fichiers trop gros mis à la fin de l'ISO

}
    if (destinationIO->currentSector() != endOfFilledIso) {
        qWarning() << "destination error 3b" << destinationIO->currentSector() << _io.sectorCount();
    }
    if (destinationIO->pos() != _io.pos()) {
        qWarning() << "destination error 3c" << destinationIO->pos() << _io.pos();
    }
#endif

    // Fichiers trop gros mis à la fin de l'ISO
    for (const IsoFile *isoFile : std::as_const(writeToTheEnd)) {
        if (control && control->observerWasCanceled()) {
            setError(Archive::AbortError);
            return false;
        }
#ifdef ISOARCHIVE_DEBUG
        qWarning() << "Write file at the end" << isoFile->name() << destinationIO->currentSector();
#endif

        if (!destination->writeFile(isoFile->modifiedFile(), 0, control)) {
