void LZS::InsertNode(qint32 r)
{
    /* Inserts string of length 18, text_buf[r..r+18-1], into one of the trees (text_buf[r]'th tree) and returns the longest-match position and length via the global variables match_position and match_length.
	If match_length = 18, then removes the old node in favor of the new one, because the old one will be deleted sooner.
	Note r plays double role, as tree node and position in buffer. */

    qint32 i, p, cmp;
    unsigned char *key;

    cmp = 1;
    key = &text_buf[r];
    p = 4097 + key[0];

    rson[r] = lson[r] = 4096;
    match_length = 0;

    forever {
        if (cmp >= 0) {
            if (rson[p] != 4096) {
                p = rson[p];
            } else {
                rson[p] = r;
                dad[r] = p;

                return;
            }
        } else {
            if (lson[p] != 4096) {
                p = lson[p];
            } else {
                lson[p] = r;
                dad[r] = p;

                return;
            }
        }

        for (i = 1; i < 18; i++) {
            if ((cmp = key[i] - text_buf[p + i]) != 0) {
                break;
            }
        }

        if (i > match_length) {
            match_position = p;
            if ((match_length = i) >= 18) {
                break;
            }
        }
    }

    dad[r] = dad[p];

if (i > match_length) {
            match_position = p;
            if ((match_length = i) >= 18) {
                break;
            }
        }
    }

    dad[r] = dad[p];
    lson[r] = lson[p];
    rson[r] = rson[p];

    dad[lson[p]] = r;
    dad[rson[p]] = r;

    if (rson[dad[p]] == p) {
        rson[dad[p]] = r;
    } else {
        lson[dad[p]] = r;
    }
    dad[p] = 4096; // remove p
}

void LZS::DeleteNode(qint32 p) // deletes node p from tree
{
    qint32 q;
    if (dad[p] == 4096) {
        return; // not in tree
    }

    if (rson[p] == 4096) {
        q = lson[p];
    } else if (lson[p] == 4096) {
        q = rson[p];
    }
    else {
        q = lson[p];
        if (rson[q] != 4096) {
            do {
                q = rson[q];
            }
            while (rson[q] != 4096);

            rson[dad[q]] = lson[q];
            dad[lson[q]] = dad[q];
            lson[q] = lson[p];
            dad[lson[p]] = q;
        }
        rson[q] = rson[p];
        dad[rson[p]] = q;
    }
    dad[q] = dad[p];

    if (rson[dad[p]] == p) {
        rson[dad[p]] = q;
    } else {
        lson[dad[p]] = q;
    }
    dad[p] = 4096;

dad[rson[p]] = q;
    }
    dad[q] = dad[p];

    if (rson[dad[p]] == p) {
        rson[dad[p]] = q;
    } else {
        lson[dad[p]] = q;
    }
    dad[p] = 4096;
}

