    } else {
        ret.resize(destLen);
    }
#else
    if (Z_OK != compress2(buffer, &destLen, reinterpret_cast<const Bytef *>(data), size, level)) {
        ret.clear();
    } else {
        ret.resize(destLen);
    }
#endif
    return ret;
}

ulong GZIP::crc(const char *data, int size)
{
#if (ZLIB_VERNUM < 0x1280)
    return z_crc32(z_crc32(0L, nullptr, 0), reinterpret_cast<const Bytef *>(data), size);
#else
    return crc32(crc32(0L, nullptr, 0), reinterpret_cast<const Bytef *>(data), size);
#endif
}

char GZIP::strategyToChar(Strategy strategy)
{
    switch (strategy) {
    case StrategyDefault:     return '*';
    case StrategyFiltered:    return 'f';
    case StrategyHuffmanOnly: return 'h';
    case StrategyRle:         return 'R';
    case StrategyFixed:       return 'F';
    }
    return '*';
}

QString GZIP::gzMode(const char *mode, int level, Strategy strategy)
{
    QString m = QString::fromLatin1(mode);
    if (level >= 0 && level <= 9) {
        m.append(QString::number(level));
    }
    char s = strategyToChar(strategy);
    if (s != '*') {
        m.append(s);
    }
    return m;
}

