quint16 FF7Save::ff7Checksum(int s)
{
    QByteArray data = slotFF7Data(s).mid(4, 0x10F0);
    int i = 0;
    quint16 r = 0xFFFF, len = 0x10F0, pbit = 0x8000;
    while (len--) {
        int t = data.at(i++);
        r ^= t << 8;
        for (int d = 0; d < 8; d++) {
            if (r & pbit)
                r = quint16(r << 1) ^ 0x1021;
            else
                r <<= 1;
        }
        r &= (1 << 16) - 1;

while (len--) {
        int t = data.at(i++);
        r ^= t << 8;
        for (int d = 0; d < 8; d++) {
            if (r & pbit)
                r = quint16(r << 1) ^ 0x1021;
            else
                r <<= 1;
        }
        r &= (1 << 16) - 1;
    }
    return ((r ^ 0xFFFF) & 0xFFFF);
}

