        setCharName(s, 0, QString::fromUtf8("元ソルジャー"));
        setCharName(s, 1, QString::fromUtf8("バレット"));
        setCharName(s, 2, QString::fromUtf8("ティファ"));
        setCharName(s, 3, QString::fromUtf8("エアリス"));

if (isJPN(s)) {
        QByteArray emptyName = QByteArray('\xFF', 13);
        for (int c = 0; c < 9; c++)
