    let newW = Math.max(1, width)
    let newH = Math.max(1, height)

    // Adjust position if needed to fit within 320x240 screen
    if (newX + newW > SCREEN_W) {
      newX = SCREEN_W - newW
    }
    if (newY + newH > SCREEN_H) {
