          <input
            type="range"
            className="w-full"
            min={0}
            max={255}
            step={1}
            value={outerRadius}
            onChange={(e) => handleOuterRadiusChange(parseInt(e.target.value, 10))}
          />
        </div>

        <div className="space-y-1">
          <Label className="text-xs">
            Inner Radius: {innerRadius}

max={255}
            step={1}
            value={outerRadius}
            onChange={(e) => handleOuterRadiusChange(parseInt(e.target.value, 10))}
          />
        </div>

        <div className="space-y-1">
          <Label className="text-xs">
            Inner Radius: {innerRadius}
          </Label>
          <input
            type="range"
            className="w-full"
            min={0}
            max={255}
            step={1}
            value={innerRadius}
            onChange={(e) => handleInnerRadiusChange(parseInt(e.target.value, 10))}
          />
        </div>
      </div>

      {/* Visualization */}
      <div className="space-y-2">
        <Label className="text-xs text-muted-foreground">Visualization</Label>
        <div 
          className="border border-border rounded-md bg-background relative overflow-hidden"
          style={{ width: containerSize, height: containerSize }}
        >
          <svg 
            width={containerSize} 
            height={containerSize} 
            className="absolute inset-0"
          >
            {/* Grid lines */}
            <defs>
              <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
                <path d="M 20 0 L 0 0 0 20" fill="none" stroke="#cccccc" strokeWidth="0.5" opacity="0.3"/>
              </pattern>
              {scaledTotalOuterRadius > scaledInnerRadius && (
                <radialGradient
                  id={gradientId}
                  gradientUnits="userSpaceOnUse"
                  cx={centerX}
                  cy={centerY}
                  r={scaledTotalOuterRadius}
                >
                  {/* No effect inside inner radius */}
                  <stop
                    offset={`${Math.max(0, (innerOffset - 0.001) * 100)}%`}
                    stopColor="hsl(var(--primary))"
                    stopOpacity="0"
                  />
                  {/* Start fade exactly at inner radius */}
                  <stop
                    offset={`${Math.max(0, Math.min(1, innerOffset)) * 100}%`}
                    stopColor="hsl(var(--primary))"
                    stopOpacity="0.4"
                  />

offset={`${Math.max(0, (innerOffset - 0.001) * 100)}%`}
                    stopColor="hsl(var(--primary))"
                    stopOpacity="0"
                  />
                  {/* Start fade exactly at inner radius */}
                  <stop
                    offset={`${Math.max(0, Math.min(1, innerOffset)) * 100}%`}
                    stopColor="hsl(var(--primary))"
                    stopOpacity="0.4"
                  />
                  {/* Fully faded out at outer radius */}
                  <stop offset="100%" stopColor="hsl(var(--primary))" stopOpacity="0" />
                </radialGradient>
              )}
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
            {scaledTotalOuterRadius > scaledInnerRadius && (
              <circle
                cx={centerX}
                cy={centerY}
                r={scaledTotalOuterRadius}
                fill={`url(#${gradientId})`}
              />
            )}

            {/* Outer circle (inner + outer radius) */}
            {scaledTotalOuterRadius > scaledInnerRadius && (
              <circle
                cx={centerX}
                cy={centerY}
                r={scaledTotalOuterRadius}
                fill="none"
                stroke="none"
              />
            )}

            {/* Inner circle (inner radius only) */}
            {scaledInnerRadius > 0 && (
              <circle
                cx={centerX}
                cy={centerY}
                r={scaledInnerRadius}
                fill="hsl(var(--primary))"
                fillOpacity="0.4"
                stroke="hsl(var(--primary))"
                strokeWidth="2"
              />
            )}

            {/* Center point */}
            <circle
              cx={centerX}
              cy={centerY}
              r="2"
              fill="hsl(var(--foreground))"
            />
          </svg>
        </div>
        <p className="text-xs text-muted-foreground">
          Grid lines represent mesh lines. 8 units is roughly the size of one mesh square.

import { useMemo } from "react"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import type { CallContext } from "@/components/script/types"
import { Description } from "@/components/script/Description"
import { modelsMapping } from "@/ff7/worldscript/constants"

export function EntityModelSelectUI({
  ctx,
  onBatch,
}: {
  ctx: CallContext
  onBatch: (updates: Array<{ index: number; newText: string }>) => void
}) {
  const entries: Array<{ value: number; slug: string }> = useMemo(() => {
    return Object.entries(modelsMapping).map(([k, v]) => ({ value: Number(k), slug: v }))
  }, [])
  const raw = ctx.args[0]?.text?.trim() || ""
  const slugMatch = raw.match(/^Entities\.([A-Za-z0-9_]+)$/i)
  let currentValue: number | "" = ""
  if (slugMatch) {
    const slug = slugMatch[1]
    const found = entries.find((e) => e.slug === slug)
    currentValue = found ? found.value : ""
  } else {
    const n = parseInt(raw || "0", 10)
    currentValue = Number.isNaN(n) ? "" : n
  }
  return (
    <div className="space-y-2">
      <div className="text-xs font-medium">
        {ctx.namespace}.{ctx.method}
      </div>
      {ctx.description && <Description>{ctx.description}</Description>}
      <div className="space-y-1">
        <Label className="text-xs">Model</Label>
        <Select
          value={currentValue === "" ? "" : String(currentValue)}
          onValueChange={(v) => {
            const value = parseInt(v, 10)
            const found = entries.find((e) => e.value === value)
            const newText = found ? `Entities.${found.slug}` : String(value)
            onBatch([{ index: 0, newText }])
          }}
        >
          <SelectTrigger className="h-7 text-xs">
            <SelectValue placeholder="Select model" />
          </SelectTrigger>
          <SelectContent>
            {entries.map((e) => (
              <SelectItem key={e.value} value={String(e.value)} className="text-xs">
                {e.value} - {e.slug}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    </div>
  )
}

