        </div>
        <div className="space-y-2 flex-1 w-24">
          <div>
            <div className="space-y-1">
              {uvCoords.map((coords, i) => (
                <div key={i} className="grid grid-cols-2 gap-1">
                  <div>
                    {i === 0 && <Label className="text-[10px] pl-2 block h-4">U</Label>}
