export function WorldMesh({
  renderingMode,
  onTriangleSelect,
  selectedFaceIndex,
  debugCanvasRef,
  mapCenter,
  rotation,
  showGrid = false,
  disablePainting,
  wireframe,
  showNormals = false,
  mode,
  gridActiveOverride,
  preselectedCell,
  onWireframeOpacityUpdate,
}: WorldMeshProps) {
  // useTraceUpdate({ renderingMode, onTriangleSelect, selectedFaceIndex, debugCanvasRef, mapCenter, rotation, showGrid, disablePainting, wireframe, showNormals, mode, gridActiveOverride, preselectedCell });

  const [mouseDownPos, setMouseDownPos] = useState<{ x: number; y: number } | null>(null);
  const [paintingMouseDownPos, setPaintingMouseDownPos] = useState<{ x: number; y: number } | null>(null);
  const [paintingDragActive, setPaintingDragActive] = useState(false);
  const [paintingDragStartMode, setPaintingDragStartMode] = useState<boolean | null>(null);
  const [paintingHasToggled, setPaintingHasToggled] = useState(false);
  const wireframeMaterialRef = useRef<THREE.MeshBasicMaterial | null>(null);
  const { textures, worldmap, mapType, paintingSelectedTriangles, togglePaintingSelectedTriangle, setTriangleMap } = useMaps();

  const { loadTextureAtlas } = useTextureAtlas();
  const { texture, canvas, texturePositions } = loadTextureAtlas(textures, mapType);

  const { geometry, normalLinesGeometry, triangleMap, updateTrianglePosition, updateColors, updateTriangleTexture, updateTriangleNormals } = useGeometry(worldmap, mapType, renderingMode, textures, texturePositions);
  const selectedTriangleGeometry = useSelectedTriangleGeometry(triangleMap, selectedFaceIndex);

const [paintingDragStartMode, setPaintingDragStartMode] = useState<boolean | null>(null);
  const [paintingHasToggled, setPaintingHasToggled] = useState(false);
  const wireframeMaterialRef = useRef<THREE.MeshBasicMaterial | null>(null);
  const { textures, worldmap, mapType, paintingSelectedTriangles, togglePaintingSelectedTriangle, setTriangleMap } = useMaps();

  const { loadTextureAtlas } = useTextureAtlas();
  const { texture, canvas, texturePositions } = loadTextureAtlas(textures, mapType);

  const { geometry, normalLinesGeometry, triangleMap, updateTrianglePosition, updateColors, updateTriangleTexture, updateTriangleNormals } = useGeometry(worldmap, mapType, renderingMode, textures, texturePositions);
  const selectedTriangleGeometry = useSelectedTriangleGeometry(triangleMap, selectedFaceIndex);


  // Callback to update wireframe opacity based on camera height
  const updateWireframeOpacity = useCallback((cameraHeight: number) => {
    if (wireframeMaterialRef.current) {
      const opacity = cameraHeight
        ? Math.max(0, 0.3 * (1 - Math.max(0, (cameraHeight - 1000) / 5000)))
        : 0.2;
      wireframeMaterialRef.current.opacity = opacity;
    }
  }, []);

  // Provide the update function to parent component
  useEffect(() => {
    if (onWireframeOpacityUpdate) {
      onWireframeOpacityUpdate(updateWireframeOpacity);
    }
  }, [onWireframeOpacityUpdate, updateWireframeOpacity]);

  // Update triangleMap in global state whenever it changes
  useEffect(() => {
    if (triangleMap) {
      setTriangleMap(
        triangleMap,
        updateColors,
        updateTriangleTexture,
        updateTriangleNormals,
        updateTrianglePosition
      );
    }
  }, [triangleMap, setTriangleMap, updateColors, updateTriangleTexture, updateTriangleNormals, updateTrianglePosition]);

  // Copy the texture atlas to the debug canvas
  useEffect(() => {
    if (debugCanvasRef.current && canvas) {
      const ctx = debugCanvasRef.current.getContext('2d');
      if (ctx) {
        ctx.clearRect(0, 0, 512, 512);
        ctx.drawImage(canvas, 0, 0, 512, 512);
      }
    }
  }, [canvas, debugCanvasRef]);

  const handlePointerDown = (event: ThreeEvent<PointerEvent>) => {
    setMouseDownPos({ x: event.clientX, y: event.clientY });
  };

  const handleClick = (event: ThreeEvent<MouseEvent>) => {
    if (mode === 'export' || !mouseDownPos || !onTriangleSelect) return;

}
  }, [canvas, debugCanvasRef]);

  const handlePointerDown = (event: ThreeEvent<PointerEvent>) => {
    setMouseDownPos({ x: event.clientX, y: event.clientY });
  };

  const handleClick = (event: ThreeEvent<MouseEvent>) => {
    if (mode === 'export' || !mouseDownPos || !onTriangleSelect) return;

    // Check if mouse moved more than 5 pixels in any direction
    const dx = Math.abs(event.clientX - mouseDownPos.x);
    const dy = Math.abs(event.clientY - mouseDownPos.y);
    const isDrag = dx > 5 || dy > 5;

    setMouseDownPos(null);

    if (!isDrag && triangleMap && event.faceIndex !== undefined) {
      const selectedTriangle = triangleMap[event.faceIndex];
      (window as any).selectedTriangle = selectedTriangle;
      onTriangleSelect(selectedTriangle, event.faceIndex);
    }
  };

  const handlePaintingPointerDown = (event: ThreeEvent<PointerEvent>) => {
    if (event.button !== 0 || disablePainting) return;
    setPaintingMouseDownPos({ x: event.clientX, y: event.clientY });
    if (mode === 'painting' && typeof event.faceIndex === 'number') {
      const alreadySelected = paintingSelectedTriangles.has(event.faceIndex);
      setPaintingDragStartMode(alreadySelected);
      togglePaintingSelectedTriangle(event.faceIndex, !alreadySelected);
      setPaintingHasToggled(true);
    }
  };

  const handlePaintingPointerMove = (event: ThreeEvent<PointerEvent>) => {
    if (disablePainting) return;
    if (!paintingMouseDownPos) return;
    const dx = Math.abs(event.clientX - paintingMouseDownPos.x);
    const dy = Math.abs(event.clientY - paintingMouseDownPos.y);
    if (dx > 5 || dy > 5) {
      setPaintingDragActive(true);
      if (mode === 'painting' && typeof event.faceIndex === 'number' && paintingDragStartMode !== null) {
        const shouldAdd = !paintingDragStartMode;
        togglePaintingSelectedTriangle(event.faceIndex, shouldAdd);
      }
    }
  };

  const handlePaintingClick = (event: ThreeEvent<MouseEvent>) => {
    if (event.button !== 0 || disablePainting) return;
    if (mode === 'painting' && typeof event.faceIndex === 'number') {
      if (!paintingDragActive && !paintingHasToggled) {
        const isSelected = paintingSelectedTriangles.has(event.faceIndex);
        togglePaintingSelectedTriangle(event.faceIndex, !isSelected);
      }
    }
    setPaintingDragActive(false);
    setPaintingDragStartMode(null);
    setPaintingMouseDownPos(null);

if (event.button !== 0 || disablePainting) return;
    if (mode === 'painting' && typeof event.faceIndex === 'number') {
      if (!paintingDragActive && !paintingHasToggled) {
        const isSelected = paintingSelectedTriangles.has(event.faceIndex);
        togglePaintingSelectedTriangle(event.faceIndex, !isSelected);
      }
    }
    setPaintingDragActive(false);
    setPaintingDragStartMode(null);
    setPaintingMouseDownPos(null);
    setPaintingHasToggled(false);
  };

  if (!geometry || !triangleMap) {
    // Show loading indicator when worldmap exists but geometry is still being computed
    if (worldmap && worldmap.length > 0) {
      return (
        <group>
          <mesh>
            <boxGeometry args={[100, 100, 100]} />
            <meshBasicMaterial color="#666" transparent opacity={0.3} />
          </mesh>
        </group>
      );
    }
    return null;
  }

  return (
    <group>
      <group 
        position={[mapCenter.x, 0, mapCenter.z]}
        rotation={[0, rotation, 0]}
      >
        <group position={[-mapCenter.x, 0, -mapCenter.z]}>
          <mesh 
            geometry={geometry}
            onPointerDown={mode === 'painting' ? handlePaintingPointerDown : handlePointerDown}
            onPointerMove={mode === 'painting' ? handlePaintingPointerMove : undefined}
            onClick={mode === 'painting' ? handlePaintingClick : handleClick}
            renderOrder={0}
          >
            {renderingMode === "textured" && texture ? (
              <meshBasicMaterial 
                map={texture} 
                side={THREE.DoubleSide}
                transparent={true}
                alphaTest={0.5}
                toneMapped={false}
              />
            ) : (
              <meshPhongMaterial vertexColors side={THREE.DoubleSide} />
            )}
          </mesh>
          {wireframe && (
            <mesh geometry={geometry} renderOrder={10}>
              <meshBasicMaterial
                ref={wireframeMaterialRef}
                color="#000000"
                wireframe={true}

) : (
              <meshPhongMaterial vertexColors side={THREE.DoubleSide} />
            )}
          </mesh>
          {wireframe && (
            <mesh geometry={geometry} renderOrder={10}>
              <meshBasicMaterial
                ref={wireframeMaterialRef}
                color="#000000"
                wireframe={true}
                transparent={true}
                opacity={0.2}
                depthTest={true}
                depthWrite={true}
              />
            </mesh>
          )}
          {showNormals && normalLinesGeometry && (
            <lineSegments geometry={normalLinesGeometry} renderOrder={11}>
              <lineBasicMaterial 
                color="#00ff00" 
                linewidth={1}
                transparent={true}
                opacity={0.5}
                depthTest={true}
                depthWrite={true}
              />
            </lineSegments>
          )}
          {onTriangleSelect && selectedTriangleGeometry && (
            <lineSegments renderOrder={10}>
              <edgesGeometry attach="geometry" args={[selectedTriangleGeometry]} />
              <lineBasicMaterial 
                color="#ff00ff" 
                linewidth={2} 
                depthTest={false} 
                depthWrite={false}
                transparent
              />
            </lineSegments>
          )}
          {showGrid && (
            <GridOverlay 
              worldmapLength={worldmap.length} 
              worldmapWidth={worldmap[0].length} 
              active={typeof gridActiveOverride === 'boolean' ? gridActiveOverride : (mode === 'export')}
              preselectedCell={preselectedCell}
            />
          )}
          {mode === 'painting' && paintingSelectedTriangles.size > 0 && triangleMap && (
            Array.from(paintingSelectedTriangles).map(faceIndex => {
              const tri = triangleMap[faceIndex];
              if (!tri) return null;
              const highlightPositions = new Float32Array(9);
              highlightPositions.set([
                tri.transformedVertices.v0[0], tri.transformedVertices.v0[1] + SELECTION_Y_OFFSET, tri.transformedVertices.v0[2],
                tri.transformedVertices.v1[0], tri.transformedVertices.v1[1] + SELECTION_Y_OFFSET, tri.transformedVertices.v1[2],
                tri.transformedVertices.v2[0], tri.transformedVertices.v2[1] + SELECTION_Y_OFFSET, tri.transformedVertices.v2[2]
              ], 0);
              const selectedGeometry = new THREE.BufferGeometry();

Array.from(paintingSelectedTriangles).map(faceIndex => {
              const tri = triangleMap[faceIndex];
              if (!tri) return null;
              const highlightPositions = new Float32Array(9);
              highlightPositions.set([
                tri.transformedVertices.v0[0], tri.transformedVertices.v0[1] + SELECTION_Y_OFFSET, tri.transformedVertices.v0[2],
                tri.transformedVertices.v1[0], tri.transformedVertices.v1[1] + SELECTION_Y_OFFSET, tri.transformedVertices.v1[2],
                tri.transformedVertices.v2[0], tri.transformedVertices.v2[1] + SELECTION_Y_OFFSET, tri.transformedVertices.v2[2]
              ], 0);
              const selectedGeometry = new THREE.BufferGeometry();
              selectedGeometry.setAttribute('position', new THREE.Float32BufferAttribute(highlightPositions, 3));
              selectedGeometry.computeVertexNormals();
              return (
                <group key={faceIndex}>
                  {/* White semi-transparent fill */}
                  <mesh geometry={selectedGeometry} renderOrder={9}>
                    <meshBasicMaterial 
                      color="#ffffff" 
                      transparent={true}
                      opacity={0.33}
                      side={THREE.DoubleSide}
                      depthTest={false}
                      depthWrite={false}
                    />
                  </mesh>
                  {/* Magenta outline */}
                  <lineSegments renderOrder={10}>
                    <edgesGeometry attach="geometry" args={[selectedGeometry]} />
                    <lineBasicMaterial 
                      color="#000" 
                      opacity={0.33}
                      depthTest={false} 
                      depthWrite={false}
                      transparent
                    />
                  </lineSegments>
                </group>
              );
            })
          )}
        </group>
      </group>
    </group>
  );
}

import * as THREE from 'three';
import { WorldMapTexture } from '@/ff7/texfile';
import { ATLAS_SIZE, TEXTURE_PADDING } from '../../constants';
import { TextureAtlasResult } from '../../types';

export function createTextureAtlas(textures: WorldMapTexture[]): TextureAtlasResult {
  // Create a texture atlas of 1024x1024 pixels
  const canvas = document.createElement('canvas');
  canvas.width = ATLAS_SIZE;
  canvas.height = ATLAS_SIZE;
  const ctx = canvas.getContext('2d')!;

  // Use transparent black as background
  ctx.clearRect(0, 0, ATLAS_SIZE, ATLAS_SIZE);

  // Keep track of texture positions in the atlas
  const texturePositions = new Map<number, { x: number, y: number, name: string }>();

  // Current position in the atlas
  let currentX = 0;
  let currentY = 0;
  let rowHeight = 0;

  // For each texture that has been loaded
  let loadedCount = 0;
  textures.forEach((texture) => {
    if (!texture.tex) return;
    loadedCount++;

    // If this texture won't fit in current row, move to next row
    if (currentX + texture.width + TEXTURE_PADDING * 2 > ATLAS_SIZE) {
      currentX = 0;
      currentY += rowHeight + TEXTURE_PADDING;
      rowHeight = 0;
    }

    // Store the position where this texture will be placed (including padding)
    texturePositions.set(texture.id, { 
      x: currentX + TEXTURE_PADDING, 
      y: currentY + TEXTURE_PADDING, 
      name: texture.name 
    });

    // Get the raw pixel data
    const pixels = texture.tex.getPixels();

    // Create an ImageData object with alpha channel
    const imageData = new ImageData(
      new Uint8ClampedArray(pixels),
      texture.width,
      texture.height
    );

    // Create a temporary canvas to draw the texture
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = texture.width + TEXTURE_PADDING * 2;
    tempCanvas.height = texture.height + TEXTURE_PADDING * 2;
    const tempCtx = tempCanvas.getContext('2d', { willReadFrequently: true })!;
    tempCtx.clearRect(0, 0, tempCanvas.width, tempCanvas.height);

texture.height
    );

    // Create a temporary canvas to draw the texture
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = texture.width + TEXTURE_PADDING * 2;
    tempCanvas.height = texture.height + TEXTURE_PADDING * 2;
    const tempCtx = tempCanvas.getContext('2d', { willReadFrequently: true })!;
    tempCtx.clearRect(0, 0, tempCanvas.width, tempCanvas.height);

    // Draw the main texture
    tempCtx.putImageData(imageData, TEXTURE_PADDING, TEXTURE_PADDING);

    // Extend edge pixels to prevent seams while preserving alpha
    extendEdgePixels(tempCtx, texture);

    // Draw the padded texture onto the atlas
    ctx.drawImage(
      tempCanvas,
      currentX,
      currentY,
      texture.width + TEXTURE_PADDING * 2,
      texture.height + TEXTURE_PADDING * 2
    );

    // Update position tracking
    currentX += texture.width + TEXTURE_PADDING * 2;
    rowHeight = Math.max(rowHeight, texture.height + TEXTURE_PADDING * 2);
  });
  console.log(`[MapViewer] Loaded ${loadedCount} textures into atlas`);
  console.log(`[MapViewer] Texture positions:`, texturePositions);

  // Create a Three.js texture from the atlas
  const texture = new THREE.CanvasTexture(canvas);
  texture.flipY = false;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  texture.generateMipmaps = true;
  texture.anisotropy = 16;
  return { texture, canvas, texturePositions };
}

function extendEdgePixels(tempCtx: CanvasRenderingContext2D, texture: WorldMapTexture) {
  const extendPixels = (sourceX: number, sourceY: number, sourceW: number, sourceH: number,
                       destX: number, destY: number, destW: number, destH: number) => {
    // Get source pixel data
    const sourceData = tempCtx.getImageData(sourceX, sourceY, sourceW, sourceH);
    const destData = tempCtx.createImageData(destW, destH);

    // Copy pixels while preserving alpha
    for (let y = 0; y < destH; y++) {
      for (let x = 0; x < destW; x++) {
        const sourceIdx = ((y % sourceH) * sourceW + (x % sourceW)) * 4;
        const destIdx = (y * destW + x) * 4;
        destData.data[destIdx] = sourceData.data[sourceIdx];       // R
        destData.data[destIdx + 1] = sourceData.data[sourceIdx + 1]; // G
        destData.data[destIdx + 2] = sourceData.data[sourceIdx + 2]; // B
        destData.data[destIdx + 3] = sourceData.data[sourceIdx + 3]; // A
      }
    }

for (let y = 0; y < destH; y++) {
      for (let x = 0; x < destW; x++) {
        const sourceIdx = ((y % sourceH) * sourceW + (x % sourceW)) * 4;
        const destIdx = (y * destW + x) * 4;
        destData.data[destIdx] = sourceData.data[sourceIdx];       // R
        destData.data[destIdx + 1] = sourceData.data[sourceIdx + 1]; // G
        destData.data[destIdx + 2] = sourceData.data[sourceIdx + 2]; // B
        destData.data[destIdx + 3] = sourceData.data[sourceIdx + 3]; // A
      }
    }

    tempCtx.putImageData(destData, destX, destY);
  };

  // Top edge
  extendPixels(
    TEXTURE_PADDING, TEXTURE_PADDING, texture.width, 1,
    TEXTURE_PADDING, 0, texture.width, TEXTURE_PADDING
  );
  // Bottom edge
  extendPixels(
    TEXTURE_PADDING, texture.height + TEXTURE_PADDING - 1, texture.width, 1,
    TEXTURE_PADDING, texture.height + TEXTURE_PADDING, texture.width, TEXTURE_PADDING
  );
  // Left edge
  extendPixels(
    TEXTURE_PADDING, TEXTURE_PADDING, 1, texture.height,
    0, TEXTURE_PADDING, TEXTURE_PADDING, texture.height
  );
  // Right edge
  extendPixels(
    texture.width + TEXTURE_PADDING - 1, TEXTURE_PADDING, 1, texture.height,
    texture.width + TEXTURE_PADDING, TEXTURE_PADDING, TEXTURE_PADDING, texture.height
  );
  // Corners
  extendPixels(
    TEXTURE_PADDING, TEXTURE_PADDING, 1, 1,
    0, 0, TEXTURE_PADDING, TEXTURE_PADDING
  );
  extendPixels(
    texture.width + TEXTURE_PADDING - 1, TEXTURE_PADDING, 1, 1,
    texture.width + TEXTURE_PADDING, 0, TEXTURE_PADDING, TEXTURE_PADDING
  );
  extendPixels(
    TEXTURE_PADDING, texture.height + TEXTURE_PADDING - 1, 1, 1,
    0, texture.height + TEXTURE_PADDING, TEXTURE_PADDING, TEXTURE_PADDING
  );
  extendPixels(
    texture.width + TEXTURE_PADDING - 1, texture.height + TEXTURE_PADDING - 1, 1, 1,
    texture.width + TEXTURE_PADDING, texture.height + TEXTURE_PADDING, TEXTURE_PADDING, TEXTURE_PADDING
  );
}

import { useMemo, useRef, useCallback, useState, useEffect, startTransition } from 'react';
import * as THREE from 'three';
import { Mesh, Triangle } from '@/ff7/mapfile';
import { WorldMapTexture } from '@/ff7/texfile';
import { MapType, RenderingMode, TriangleWithVertices } from '../../types';
import { LOCATION_COLORS, MESH_SIZE, REGION_COLORS, SCALE, SCRIPT_COLORS, SELECTION_Y_OFFSET, ATLAS_SIZE } from '../../constants';
import { calcUV } from '@/lib/utils';


export function useGeometry(
  worldmap: Mesh[][],
  mapType: MapType,
  renderingMode: RenderingMode,
  textures: WorldMapTexture[],
  texturePositions: Map<number, { x: number, y: number, name: string }>
) {
  const geometryRef = useRef<THREE.BufferGeometry | null>(null);
  const triangleMapRef = useRef<TriangleWithVertices[] | null>(null);
  // New ref to track mapping from vertex ID to positions buffer offsets.
  const vertexOffsetsRef = useRef<Map<number, [number, Triangle][]> | null>(null);
  const [geometryResult, setGeometryResult] = useState<{ geometry: THREE.BufferGeometry | null, triangleMap: TriangleWithVertices[] | null }>({ geometry: null, triangleMap: null });

  const computeGeometry = useCallback(() => {
    if (!worldmap || !worldmap.length) {
      setGeometryResult({ geometry: null, triangleMap: null });
      return;
    }

    // Use startTransition to make this computation non-blocking
    startTransition(() => {
      let totalTris = 0;
      for (const row of worldmap) {
        for (const mesh of row) {
          totalTris += mesh.numTriangles;
        }
      }

      // Allocate buffers (positions, colors, uvs) as before.
      const positions = new Float32Array(totalTris * 3 * 3);
      const colors = new Float32Array(totalTris * 3 * 3);
      const uvs = new Float32Array(totalTris * 3 * 2);

      const triangleMap: TriangleWithVertices[] = [];

      let offset = 0;
      let uvOffset = 0;
      let triangleIndex = 0;

      // For shared vertices, assign a unique ID and record where in the positions buffer they are written.
      let vertexIdCounter = 0;
      const uniqueVertexMap = new Map<string, number>(); // key -> vertexId
      const vertexIdToOffsets = new Map<number, [number, Triangle][]>(); // vertexId -> [offsets]

      const terrainColorMap = LOCATION_COLORS[mapType];
      const regionColorMap = REGION_COLORS[mapType];
      const defaultColor = new THREE.Color('#444');

      // Process each mesh and its triangles
      for (let row = 0; row < worldmap.length; row++) {
        for (let col = 0; col < worldmap[row].length; col++) {

const uniqueVertexMap = new Map<string, number>(); // key -> vertexId
      const vertexIdToOffsets = new Map<number, [number, Triangle][]>(); // vertexId -> [offsets]

      const terrainColorMap = LOCATION_COLORS[mapType];
      const regionColorMap = REGION_COLORS[mapType];
      const defaultColor = new THREE.Color('#444');

      // Process each mesh and its triangles
      for (let row = 0; row < worldmap.length; row++) {
        for (let col = 0; col < worldmap[row].length; col++) {
          const mesh = worldmap[row][col];
          const offsetX = col * MESH_SIZE;
          const offsetZ = row * MESH_SIZE;

          for (const tri of mesh.triangles) {
            const transformedVertices = {
              v0: [0, 0, 0] as [number, number, number],
              v1: [0, 0, 0] as [number, number, number],
              v2: [0, 0, 0] as [number, number, number]
            };

            let color: THREE.Color;
            if (renderingMode === "region") {
              const regionIdx = tri.locationId % 32;
              const colorHex = regionColorMap[regionIdx];
              color = colorHex ? new THREE.Color(colorHex) : defaultColor;
            } else if (renderingMode === "terrain") {
              const colorHex = terrainColorMap[tri.type];
              color = colorHex ? new THREE.Color(colorHex) : defaultColor;
            } else if (renderingMode === "scripts") {
              if (tri.isChocobo) {
                color = new THREE.Color(SCRIPT_COLORS.chocobo);
              } else if (tri.script > 0) {
                color = new THREE.Color(SCRIPT_COLORS.script[tri.script as keyof typeof SCRIPT_COLORS.script] || SCRIPT_COLORS.script[8]);
              } else {
                color = new THREE.Color(SCRIPT_COLORS.none);
              }
            } else {
              color = new THREE.Color('#fff');
            }

            // Updated helper: write the vertex, assign a unique vertexId, and record its offset.
            function setPosColor(v: { x: number, y: number, z: number }, vertexIndex: 0 | 1 | 2): number {
              const x = (v.x + offsetX) * SCALE;
              const y = v.y * SCALE;
              const z = (v.z + offsetZ) * SCALE;

              // Use a key based on the absolute position (rounded to avoid floating point issues)
              const key = `${Math.round(x * 1000) / 1000},${Math.round(y * 1000) / 1000},${Math.round(z * 1000) / 1000}`;
              let vertexId: number;
              if (uniqueVertexMap.has(key)) {
                vertexId = uniqueVertexMap.get(key)!;
              } else {
                vertexId = vertexIdCounter++;
                uniqueVertexMap.set(key, vertexId);
                vertexIdToOffsets.set(vertexId, []);
              }
              // Record this occurrence (offset in the positions array) for the vertexId.
              vertexIdToOffsets.get(vertexId)!.push([offset, tri]);

if (uniqueVertexMap.has(key)) {
                vertexId = uniqueVertexMap.get(key)!;
              } else {
                vertexId = vertexIdCounter++;
                uniqueVertexMap.set(key, vertexId);
                vertexIdToOffsets.set(vertexId, []);
              }
              // Record this occurrence (offset in the positions array) for the vertexId.
              vertexIdToOffsets.get(vertexId)!.push([offset, tri]);

              // Write position and color into buffers.
              positions[offset] = x;
              positions[offset + 1] = y;
              positions[offset + 2] = z;
              colors[offset] = color.r;
              colors[offset + 1] = color.g;
              colors[offset + 2] = color.b;

              // Save transformed vertex.
              transformedVertices[`v${vertexIndex}`] = [x, y, z];
              offset += 3;
              return vertexId;
            }

            // Process each vertex of the triangle and get its unique ID.
            const vertexId0 = setPosColor(tri.vertex0, 0);
            const vertexId1 = setPosColor(tri.vertex1, 1);
            const vertexId2 = setPosColor(tri.vertex2, 2);

            // UV calculation for textured mode
            const texture = textures[tri.texture];
            const isUnderwaterOutside = texture?.name.includes("cltr") && tri.uVertex0 === 254;
            if (texture && texturePositions?.has(tri.texture) && !isUnderwaterOutside) {
              const pos = texturePositions.get(tri.texture)!;
              const u0 = (pos.x + calcUV(tri.uVertex0, texture.uOffset, texture.width)) / ATLAS_SIZE;
              const v0 = (pos.y + calcUV(tri.vVertex0, texture.vOffset, texture.height)) / ATLAS_SIZE;
              const u1 = (pos.x + calcUV(tri.uVertex1, texture.uOffset, texture.width)) / ATLAS_SIZE;
