    const offsetZ = row * MESH_SIZE;

    // Start point of the line (vertex position)
    const startX = (vertex.x + offsetX) * SCALE;
    const startY = vertex.y * SCALE;
    const startZ = (vertex.z + offsetZ) * SCALE;    

