    positions[lineOffset] = startX;
    positions[lineOffset + 1] = startY;
    positions[lineOffset + 2] = startZ;

    // End point is vertex + scaled normal
    positions[lineOffset + 3] = startX + normal.x * SCALE * normalScale / 4096;
