import { atom, useAtom } from 'jotai'
import * as THREE from 'three'
import { WorldMapTexture } from '@/ff7/texfile'
import { MapType } from '@/components/map/types'
import { createTextureAtlas } from '@/components/map/components/WorldMesh/utils'

interface TextureAtlasState {
  texture: THREE.Texture | null
  canvas: HTMLCanvasElement | null
  texturePositions: Map<number, { x: number, y: number, name: string }>
  loadedTextures: WorldMapTexture[]
  mapType: MapType | null
}

const textureAtlasStateAtom = atom<TextureAtlasState>({
  texture: null,
  canvas: null,
  texturePositions: new Map<number, { x: number, y: number, name: string }>(),
  loadedTextures: [],
  mapType: null,
})

export function useTextureAtlas() {
  const [state, setState] = useAtom(textureAtlasStateAtom)

  const loadTextureAtlas = (textures: WorldMapTexture[], mapType: MapType) => {
    // Check if all textures are loaded
    const loadedTextures = textures.filter(t => t.tex !== null)

    // Check if we already have the atlas for these exact textures and map type
    const texturesChanged = loadedTextures.length !== state.loadedTextures.length ||
      !loadedTextures.every((tex, index) => tex.id === state.loadedTextures[index]?.id) ||
      mapType !== state.mapType

    if (!texturesChanged && state.texture && state.canvas && state.texturePositions.size > 0) {
      // Return existing atlas
      return {
        texture: state.texture,
        canvas: state.canvas,
        texturePositions: state.texturePositions
      }
    }

    // Only create texture atlas when all textures are loaded
    if (loadedTextures.length === 0) {
      console.log('[MapViewer] No textures loaded yet, skipping atlas creation')
      const emptyResult = {
        texture: null,
        canvas: null,
        texturePositions: new Map<number, { x: number, y: number, name: string }>(),
        loadedTextures: [],
        mapType: null
      }
      setState(emptyResult)
      return { texture: null, canvas: null, texturePositions: emptyResult.texturePositions }
    }

    console.log(`[MapViewer] Creating texture atlas for ${mapType}...`)
    const result = createTextureAtlas(loadedTextures)

loadedTextures: [],
        mapType: null
      }
      setState(emptyResult)
      return { texture: null, canvas: null, texturePositions: emptyResult.texturePositions }
    }

    console.log(`[MapViewer] Creating texture atlas for ${mapType}...`)
    const result = createTextureAtlas(loadedTextures)

    setState({
      ...result,
      loadedTextures,
      mapType
    })

    return result
  }

  const resetTextureAtlas = () => {
    setState({
      texture: null,
      canvas: null,
      texturePositions: new Map<number, { x: number, y: number, name: string }>(),
      loadedTextures: [],
      mapType: null,
    })
  }

  return {
    texture: state.texture,
    canvas: state.canvas,
    texturePositions: state.texturePositions,
    loadTextureAtlas,
    resetTextureAtlas
  }
}

import { atom, useAtom } from 'jotai'
import { useCallback, useEffect } from 'react'
import { invoke } from "@tauri-apps/api/core";

interface AppState {
  dataPath: string | null
  opened: boolean
  openedTime: number
  connected: boolean
  loading: boolean
  loadingStep: string
  currentTab: string
  alert: {
    show: boolean
    title: string
    message: string
  }
  unsavedChanges: boolean
}

const appStateAtom = atom<AppState>({
  dataPath: null,
  opened: false,
  openedTime: 0,
  connected: false,
  loading: false,
  loadingStep: '',
  currentTab: 'messages',
  alert: {
    show: false,
    title: '',
    message: ''
  },
  unsavedChanges: false
})

export function useAppState() {
  const [state, setState] = useAtom(appStateAtom)

  const setDataPath = (path: string) => {
    setState(prev => ({
      ...prev,
      dataPath: path,
      opened: true,
      openedTime: Date.now(),
      unsavedChanges: false
    }))
  }

  const setLoading = (loading: boolean) => {
    setState(prev => ({ ...prev, loading, loadingStep: loading ? prev.loadingStep : '' }))
  }

  const setCurrentTab = (tab: string) => {
    setState(prev => ({ ...prev, currentTab: tab }))
  }

  const setLoadingStep = (step: string) => {
    setState(prev => ({ ...prev, loading: true, loadingStep: step }))
  }

setState(prev => ({ ...prev, loading, loadingStep: loading ? prev.loadingStep : '' }))
  }

  const setCurrentTab = (tab: string) => {
    setState(prev => ({ ...prev, currentTab: tab }))
  }

  const setLoadingStep = (step: string) => {
    setState(prev => ({ ...prev, loading: true, loadingStep: step }))
  }

  const showAlert = (title: string, message: string) => {
    setState(prev => ({
      ...prev,
      alert: {
        show: true,
        title,
        message
      }
    }))
  }

  const hideAlert = () => {
    setState(prev => ({
      ...prev,
      alert: {
        show: false,
        title: '',
        message: ''
      }
    }))
  }

  const markUnsavedChanges = useCallback(() => {
    setState(prev => (prev.unsavedChanges ? prev : { ...prev, unsavedChanges: true }))
  }, [setState])

  const clearUnsavedChanges = useCallback(() => {
    setState(prev => (prev.unsavedChanges ? { ...prev, unsavedChanges: false } : prev))
  }, [setState])

  const checkConnection = async () => {
    try {
      const isRunning = await invoke<boolean>('is_ff7_running')
      setState(prev => ({ ...prev, connected: isRunning }))
    } catch (error) {
      console.error('Failed to check FF7 connection:', error)
      setState(prev => ({ ...prev, connected: false }))
    }
  }

  useEffect(() => {
    // Check connection immediately
    checkConnection()

    // Then check every 2 seconds
    const interval = setInterval(checkConnection, 2000)

    return () => clearInterval(interval)
  }, [])

useEffect(() => {
    // Check connection immediately
    checkConnection()

    // Then check every 2 seconds
    const interval = setInterval(checkConnection, 2000)

    return () => clearInterval(interval)
  }, [])

  return {
    ...state,
    setDataPath,
    setLoading,
    setLoadingStep,
    setCurrentTab,
    showAlert,
    hideAlert,
    markUnsavedChanges,
    clearUnsavedChanges
  }
}

