        type: text,
        readUntil: function(byte: number) {
            return byte === 0xFF;
        }
    })

const mesMessage = new Parser()
    .uint16le('offset')
    .pointer('text', {
        type: ffText,
        offset: 'offset'
    })

const mesParser = new Parser()
    .uint16le('numMessages')
    .array('messages', {
        type: mesMessage,
        length: 'numMessages'
    })

interface Message {
    offset: number;
    text: string;
}

interface Messages {
    numMessages: number;
    messages: Message[];
}

export class MesFile {
    data: Messages;

    constructor(data?: Uint8Array) {
        if (data) {
            this.data = mesParser.parse(data);
        } else {
            this.data = {
                numMessages: 0,
                messages: []
            };
        }
    }

    readMessage(index: number) {
        return this.data.messages[index];
    }

