            // STR {offset} {length} command
            else if (k === 0xE2) {
                const offset = new DataView(buf.buffer).getUint16(i, true);
                i += 2;
                const length = new DataView(buf.buffer).getUint16(i, true);
                i += 2;
                text += `{STR ${offset} ${length}}`
            }

            // Other control codes
            else {

