const MIN_REF_LEN = 3;
const MAX_REF_LEN = 18;
const LEFT_NIBBLE_MASK = 0b11110000;
const RIGHT_NIBBLE_MASK = 0b00001111;
const WINDOW_MASK = 0x0FFF;
const WINDOW_SIZE = 0x1000;
