          this.consume('punct');
          const right = this.parseExpression();
          return { type: 'Assignment', left: expr, right };
        }
        return { type: 'ExpressionStatement', expression: expr };
    }
    throw new Error(`Unexpected token: ${token.type} ${token.value}`);
  }

  private parseIfStatement(): IfStatement {
    this.consume('keyword'); // 'if'
    const condition = this.parseExpression();
    const nextToken = this.peek();
    if (!nextToken || nextToken.type !== 'keyword' || nextToken.value !== 'then') {
      throw new Error(`Expected 'then' after condition, got ${nextToken?.type || 'none'}: ${nextToken?.value || 'none'} at index ${this.index}`);
    }
    this.consume('keyword'); // 'then'
    const thenBranch: Statement[] = [];
    while (this.peek() && (this.peek()!.type !== 'keyword' || this.peek()!.value !== 'end')) {
      thenBranch.push(this.parseStatement());
    }
    this.consume('keyword'); // 'end'
    return { type: 'If', condition, thenBranch };
  }

  private parseGotoStatement(): GotoStatement {
    this.consume('keyword'); // 'goto'
    const label = this.consume('identifier').value;
    return { type: 'Goto', label };
  }

  private parseLabelStatement(): LabelStatement {
    this.consume('label_delim'); // '::'
    const label = this.consume('identifier').value;
    this.consume('label_delim'); // '::'
    return { type: 'Label', label };
  }

  private parseExpression(): Expression {
    return this.parseBinaryExpression(0);
  }

  private parseUnaryExpression(): Expression {
    const token = this.peek();

    // Check if we have a unary operator
    if (token && token.type === 'operator' && ['!', '-'].includes(token.value)) {
      const operator = this.consume('operator').value;
      const operand = this.parseUnaryExpression(); // Recursive to handle chained unary ops like !!a
      return { type: 'Unary', operator, operand };
    }

    // If no unary operator, parse a member/call expression.
    return this.parseMemberOrCall();
  }

  private parseBinaryExpression(minPrecedence: number): Expression {
    let left = this.parseUnaryExpression();

const operand = this.parseUnaryExpression(); // Recursive to handle chained unary ops like !!a
      return { type: 'Unary', operator, operand };
    }

    // If no unary operator, parse a member/call expression.
    return this.parseMemberOrCall();
  }

  private parseBinaryExpression(minPrecedence: number): Expression {
    let left = this.parseUnaryExpression();
    while (true) {
      const operatorToken = this.peek();
      if (!operatorToken || operatorToken.type !== 'operator') break;
      const operator = operatorToken.value;
      const precedence = this.getPrecedence(operator);
      if (precedence < minPrecedence) break;
      this.consume('operator');
      const right = this.parseBinaryExpression(precedence + 1);
      left = { type: 'Binary', operator, left, right };
    }
    return left;
  }

  private getPrecedence(operator: string): number {
    switch (operator) {
      case 'or':
        return 1;
      case 'and':
        return 2;
      case '<':
      case '>':
      case '<=':
      case '>=':
      case '==':
      case '!=':
        return 3;
      case '<<':
      case '>>':
        return 4;
      case '+':
      case '-':
        return 5;
      case '*':
      case '/':
        return 6;
      default:
        return 0;
    }
  }

  private parseMemberOrCall(): Expression {
    let expr = this.parsePrimary();
    while (this.peek() && (this.peek()!.value === '.' || this.peek()!.value === '[' || this.peek()!.value === '(')) {
      if (this.peek()!.value === '.') {
        this.consume('punct');
        const property = this.consume('identifier');
        expr = { type: 'Member', object: expr, property: { type: 'Identifier', name: property.value } };
      } else if (this.peek()!.value === '[') {
        this.consume('punct'); // '['
        const index = this.parseExpression();

private parseMemberOrCall(): Expression {
    let expr = this.parsePrimary();
    while (this.peek() && (this.peek()!.value === '.' || this.peek()!.value === '[' || this.peek()!.value === '(')) {
      if (this.peek()!.value === '.') {
        this.consume('punct');
        const property = this.consume('identifier');
        expr = { type: 'Member', object: expr, property: { type: 'Identifier', name: property.value } };
      } else if (this.peek()!.value === '[') {
        this.consume('punct'); // '['
        const index = this.parseExpression();
        this.consume('punct'); // ']'
        expr = { type: 'Index', base: expr, index };
      } else if (this.peek()!.value === '(') {
        this.consume('punct');
        const args: Expression[] = [];
        if (this.peek() && this.peek()!.value !== ')') {
          args.push(this.parseExpression());
          while (this.peek() && this.peek()!.value === ',') {
            this.consume('punct');
            args.push(this.parseExpression());
          }
        }
        this.consume('punct'); // ')'
        expr = { type: 'FunctionCall', callee: expr, arguments: args };
      }
    }
    return expr;
  }

  private parsePrimary(): Expression {
    const token = this.peek();
    if (!token) throw new Error('Unexpected end of input');
    if (token.type === 'number') {
      this.consume('number');
      // Support both hex (0x) and decimal numbers
      return { 
        type: 'Literal', 
        value: token.value.startsWith('0x') ? 
          parseInt(token.value, 16) : 
          parseInt(token.value, 10) 
      };
    } else if (token.type === 'identifier') {
      this.consume('identifier');
      return { type: 'Identifier', name: token.value };
    } else if (token.type === 'punct' && token.value === '(') {
      this.consume('punct');
      const expr = this.parseExpression();
      this.consume('punct'); // ')'
      return expr;
    }
    throw new Error(`Unexpected token in primary expression: ${token.type} ${token.value}`);
  }
}

// AST Node Interfaces
export interface BaseExpression {
  type: string;
}

export interface LiteralExpression extends BaseExpression {
  type: 'Literal';
  value: string | number | boolean;
}

export interface IdentifierExpression extends BaseExpression {
  type: 'Identifier';
  name: string;
}

export interface MemberExpression extends BaseExpression {
  type: 'Member';
  object: Expression;
  property: IdentifierExpression;
}

export interface FunctionCallExpression extends BaseExpression {
  type: 'FunctionCall';
  callee: Expression;
  arguments: Expression[];
}

export interface BinaryExpression extends BaseExpression {
  type: 'Binary';
  operator: string;
  left: Expression;
  right: Expression;
}

export interface UnaryExpression extends BaseExpression {
  type: 'Unary';
  operator: string;
  operand: Expression;
}

export interface IndexExpression extends BaseExpression {
  type: 'Index';
  base: Expression;
  index: Expression;
}

export type Expression = 
  | LiteralExpression
  | IdentifierExpression
  | MemberExpression
  | FunctionCallExpression
  | BinaryExpression
  | UnaryExpression
  | IndexExpression;

export interface BaseStatement {
  type: string;
}

export interface ExpressionStatement extends BaseStatement {

| FunctionCallExpression
  | BinaryExpression
  | UnaryExpression
  | IndexExpression;

export interface BaseStatement {
  type: string;
}

export interface ExpressionStatement extends BaseStatement {
  type: 'ExpressionStatement';
  expression: Expression;
}

export interface IfStatement extends BaseStatement {
  type: 'If';
  condition: Expression;
  thenBranch: Statement[];
}

export interface GotoStatement extends BaseStatement {
  type: 'Goto';
  label: string;
}

export interface LabelStatement extends BaseStatement {
  type: 'Label';
  label: string;
}

export interface AssignmentStatement extends BaseStatement {
  type: 'Assignment';
  left: Expression;
  right: Expression;
}

export interface ReturnStatement extends BaseStatement {
  type: 'Return';
}

export interface BlockStatement extends BaseStatement {
  type: 'Block';
  body: Statement[];
}

// Define Statement as a discriminated union
export type Statement = 
  | ExpressionStatement
  | IfStatement
  | GotoStatement
  | LabelStatement
  | AssignmentStatement
  | ReturnStatement
  | BlockStatement;

// Compiler types
export interface Token {
  type: string;
  value: string;
}

| LabelStatement
  | AssignmentStatement
  | ReturnStatement
  | BlockStatement;

// Compiler types
export interface Token {
  type: string;
  value: string;
}

// Instruction type for code generation
export type Instruction = 
  | { type: 'instruction'; mnemonic: string; codeParams: string[] }
  | { type: 'label'; label: string };

