FFVIIString
StringToFFVIIString( const Ogre::String& string )
{
    FFVIIString ret;

    for( size_t i = 0; i < string.size(); ++i )
    {
        ret.push_back( ascii[ string[ i ] ] );
    }

    return ret;
}



Ogre::String
FFVIIStringToString( const FFVIIString& string )
{
    Ogre::String ret;

    for( size_t i = 0; i < string.size(); ++i )
    {
        Ogre::String l = "";

        for( int j = 0; j < 256; ++j )
        {
            if( ascii[ j ] == string[ i ] )
            {
                l = j;
            }
        }

{
        Ogre::String l = "";

        for( int j = 0; j < 256; ++j )
        {
            if( ascii[ j ] == string[ i ] )
            {
                l = j;
            }
        }

        ret += l;
    }

    return ret;
}

