{
    // lastest texture page x are on the border with vram so we need get smaller tex
    u16 size_x = ( page_x >= 15 && bpp == 1 ) ? 128 : 256;
    Surface* ret = CreateSurface( size_x, 256 );

    if( clut_y > mClutHeight + mClutVramPositionY )
