                } break;

                case MOVIE:
                {
                    export_script->Log("field:play_movie();\n");
                    AdvanceScript(1, script, end);
                } break;

                case MVIEF:
                {
                    export_script->Log(
                        SetVariable(GetU8(script + 1), GetU8(script + 2), "field:get_movie_frame()")
                        );
                    AdvanceScript(3, script, end);
                } break;

                case MVCAM:
                {
                    export_script->Log(
                        "field:movie_camera_enable( " +
