//---------------------------------------------------------------------
Ogre::ColourValue
MeshFile::readColor( const u32 offset )
{
    u8 r( GetU8( offset + 0 ) )
      ,g( GetU8( offset + 1 ) )
      ,b( GetU8( offset + 2 ) )
      ,a( GetU8( offset + 3 ) );

    return Ogre::ColourValue( r / 255.0f, g / 255.0f, b / 255.0f, a / 255.0f );
}

