        texture_coords_id = GetU8(offset_to_poly + 0x17);
        x = GetU8(offset_to_texture_coords + texture_coords_id * 0x02 + 0x00) + texture.start_x;
        dt.x = x / tex_width;
        y = GetU8(offset_to_texture_coords + texture_coords_id * 0x02 + 0x01) + texture.start_y;
