                channel_data[ channel_id ].right_volume = 0 NOR channel_data[ channel_id ].right_volume;
            }
        }
        else
        {
            channel_data[ channel_id ].left_volume = ( temp * h[80049cc4]) >> 0xf;
            channel_data[ channel_id ].right_volume = ( temp * h[80049cc4]) >> 0xf;
        }
*/
    }



    u16 new_pitch = 0;
/*
    if (w[T0 + 38] & 00000010)
