void
SoundManager::PsxChannelPlay( u8 arg_channel )
{
    if( arg_channel < 16 )
    {
        // H_SPUon1
        SPUwriteRegister( 0x1f801d88, 1 << arg_channel );
    }
    else if( arg_channel >= 16 && arg_channel < 24 )
    {
        // H_SPUon2
        SPUwriteRegister( 0x1f801d8a, 1 << ( arg_channel - 16 ) );
    }
}



