void InitADSR()
{
	unsigned long r = 3;
	unsigned long rs = 1;
	unsigned long rd = 0;
	int i;

	// build the rate table according to Neill's rules
	memset(RateTable, 0, sizeof(unsigned long) * 160);

	// we start at pos 32 with the real values... everything before is 0
	for(i = 32; i < 160; i++)
	{
		if(r < 0x3FFFFFFF)
		{
			r += rs;
			rd++;
			if(rd == 5)
			{
				rd = 1;
				rs *= 2;

for(i = 32; i < 160; i++)
	{
		if(r < 0x3FFFFFFF)
		{
			r += rs;
			rd++;
			if(rd == 5)
			{
				rd = 1;
				rs *= 2;
			}
		}
		if(r > 0x3FFFFFFF)
			r = 0x3FFFFFFF;

		RateTable[i] = r;
	}
}


