}



void SPUwriteDMAMem(unsigned short *pusPSXMem, int iSize)
{
    int i;

    for ( i = 0; i < iSize; i++ )
    {
        // spu addr got by writeregister
        spuMem[spuAddr >> 1] = *pusPSXMem++;
        // inc spu addr
        spuAddr += 2;
        // wrap
        if(spuAddr > 0x7ffff)
        {
            spuAddr = 0;
        }
    }

    iWatchDog = 0;
}


