void SetPitch(int ch, unsigned short val)
{
	int NP;
	if(val > 0x3fff)
		NP = 0x3fff;
	else
		NP = val;

	s_chan[ch].iRawPitch = NP;

	NP = (44100L * NP) / 4096L;
	if(NP < 1)
		NP = 1;

	s_chan[ch].iActFreq = NP;
}


