int MixREVERBLeft(int ns)
{
	if(iUseReverb == 0)
		return 0;

	if(iUseReverb == 2)
	{
		// this func will be called with 44.1 khz
		static int iCnt = 0;

		// reverb is off
		if(!rvb.StartAddr)
		{
			rvb.iLastRVBLeft = rvb.iLastRVBRight =
				rvb.iRVBLeft = rvb.iRVBRight = 0;

			return 0;
		}

		iCnt++;

		// we work on every second left value: downsample to 22 khz
		if(iCnt & 1)
		{
