void SPUasync(unsigned long cycle)
{
	// clear the watchdog
	iWatchDog = 0;

	// special mode, only used in Linux by this spu
	// (or if you enable the experimental Windows mode)
	if(iUseTimer == 2)
	{
		// no init, no call
		if(!bSpuInit)
			return;

		// linux high-compat mode
		MAINThread(0);
	}
}



