			i++;
		}
	}

	// no more spu is running
	bThreadEnded = 0;
	bSpuInit = 0;
}


void SetupStreams(void)
{
	int i;

	// alloc mixing buffer
	pSpuBuffer = (unsigned char *)malloc(32768);

	if(iUseReverb == 1)
		i = 88200 * 2;
	else
		i = NSSIZE * 2;

	// alloc reverb buffer
	sRVBStart = (int *)malloc(i * 4);
	memset(sRVBStart, 0, i * 4);
	sRVBEnd = sRVBStart + i;
	sRVBPlay = sRVBStart;

	// alloc xa buffer
	XAStart = (u32 *)malloc(44100 * 4);
	XAPlay = XAStart;
	XAFeed = XAStart;
	XAEnd = XAStart + 44100;

	for(i = 0; i < MAXCHAN; i++)
	{
		// we don't use mutex sync... not needed, would only
		// slow us down:

		// init sustain
		s_chan[i].ADSRX.SustainLevel = 1024;
		s_chan[i].iMute = 0;
		s_chan[i].iIrqDone = 0;
		s_chan[i].pLoop = spuMemC;
		s_chan[i].pStart = spuMemC;
		s_chan[i].pCurr = spuMemC;
	}
}


void RemoveStreams(void)
{
	// free mixing buffer
	free(pSpuBuffer);

s_chan[i].pStart = spuMemC;
		s_chan[i].pCurr = spuMemC;
	}
}


void RemoveStreams(void)
{
	// free mixing buffer
	free(pSpuBuffer);
	pSpuBuffer = NULL;
	// free reverb buffer
	free(sRVBStart);
	sRVBStart = 0;
	// free xa buffer
	free(XAStart);
	XAStart = 0;
}



