unsigned short SPUgetOne(unsigned long val)
{
#ifdef DEBUG_OUTPUT
	std::cout << "*** SPUgetOne()" << std::endl;
#endif

	if(spuAddr != 0xffffffff)
	{
		return SPUreadDMA();
	}
	if(val >= 512 * 1024)
		val = 512 * 1024 - 1;
	return spuMem[val >> 1];
}



void SPUputOne(unsigned long val, unsigned short data)
{
#ifdef DEBUG_OUTPUT
	std::cout << "*** SPUputOne()" << std::endl;
#endif

	if(spuAddr != 0xffffffff)
	{
		SPUwriteDMA(data);
		return;
	}
	if(val >= 512 * 1024)
		val = 512 * 1024 - 1;
	spuMem[val >> 1] = data;
}



