	  return hard;
      case 0x1f801108:
	  hard = psxCounters[0].target;
	  return hard;
      case 0x1f801110:
	  hard = psxRcntRcount(1);
	  return hard;
      case 0x1f801114:
	  hard = psxCounters[1].mode;
	  return hard;
      case 0x1f801118:
	  hard = psxCounters[1].target;
	  return hard;
      case 0x1f801120:
	  hard = psxRcntRcount(2);
	  return hard;
      case 0x1f801124:
	  hard = psxCounters[2].mode;
	  return hard;
      case 0x1f801128:
	  hard = psxCounters[2].target;
	  return hard;

      default:
	  hard = BFLIP32(psxHu32(add));
	  return hard;
    }
    return hard;
}

