void SPUwriteRegister(u32 reg, u16 val)
{
    const u32 r = reg & 0xfff;
    regArea[(r - 0xc00) >> 1] = val;

    if (r >= 0x0c00 && r < 0x0d80)	// some channel info?
    {
	int ch = (r >> 4) - 0xc0;	// calc channel

	//if(ch==20) printf("%08x: %04x\n",reg,val);

	switch (r & 0x0f)
	{
	      //------------------------------------------------// r volume
	  case 0:
	      SetVolumeLR(0, (u8) ch, val);
	      break;
	      //------------------------------------------------// l volume
	  case 2:
	      SetVolumeLR(1, (u8) ch, val);
	      break;
	      //------------------------------------------------// pitch
	  case 4:
	      SetPitch(ch, val);
	      break;
	      //------------------------------------------------// start
	  case 6:
	      s_chan[ch].pStart = spuMemC + ((u32) val << 3);
	      break;

SetVolumeLR(1, (u8) ch, val);
	      break;
	      //------------------------------------------------// pitch
	  case 4:
	      SetPitch(ch, val);
	      break;
	      //------------------------------------------------// start
	  case 6:
	      s_chan[ch].pStart = spuMemC + ((u32) val << 3);
	      break;
	      //------------------------------------------------// level with pre-calcs
	  case 8:
	  {
	      const u32 lval = val;	// DEBUG CHECK
	      //---------------------------------------------//
	      s_chan[ch].ADSRX.AttackModeExp = (lval & 0x8000) ? 1 : 0;
	      s_chan[ch].ADSRX.AttackRate = (lval >> 8) & 0x007f;
	      s_chan[ch].ADSRX.DecayRate = (lval >> 4) & 0x000f;
	      s_chan[ch].ADSRX.SustainLevel = lval & 0x000f;
	      //---------------------------------------------//
	  }
	      break;
	      //------------------------------------------------// adsr times with pre-calcs
	  case 10:
	  {
	      const u32 lval = val;	// DEBUG CHECK

	      //----------------------------------------------//
	      s_chan[ch].ADSRX.SustainModeExp = (lval & 0x8000) ? 1 : 0;
	      s_chan[ch].ADSRX.SustainIncrease = (lval & 0x4000) ? 0 : 1;
	      s_chan[ch].ADSRX.SustainRate = (lval >> 6) & 0x007f;
	      s_chan[ch].ADSRX.ReleaseModeExp = (lval & 0x0020) ? 1 : 0;
	      s_chan[ch].ADSRX.ReleaseRate = lval & 0x001f;
	      //----------------------------------------------//
	  }
	      break;
	      //------------------------------------------------// adsr volume... mmm have to investigate this
	      //case 0xC:
	      //  break;
	      //------------------------------------------------//
	  case 0xE:		// loop?
	      s_chan[ch].pLoop = spuMemC + ((u32) val << 3);
	      s_chan[ch].bIgnoreLoop = 1;
	      break;
	      //------------------------------------------------//
	}
	return;
    }

    switch (r)
    {
	  //-------------------------------------------------//
      case H_SPUaddr:
	  spuAddr = (u32) val << 3;
	  break;
	  //-------------------------------------------------//
      case H_SPUdata:
	  spuMem[spuAddr >> 1] = BFLIP16(val);
	  spuAddr += 2;
	  if (spuAddr > 0x7ffff)

{
	  //-------------------------------------------------//
      case H_SPUaddr:
	  spuAddr = (u32) val << 3;
	  break;
	  //-------------------------------------------------//
      case H_SPUdata:
	  spuMem[spuAddr >> 1] = BFLIP16(val);
	  spuAddr += 2;
	  if (spuAddr > 0x7ffff)
	      spuAddr = 0;
	  break;
	  //-------------------------------------------------//
      case H_SPUctrl:
	  spuCtrl = val;
	  break;
	  //-------------------------------------------------//
      case H_SPUstat:
	  spuStat = val & 0xf800;
	  break;
	  //-------------------------------------------------//
      case H_SPUReverbAddr:
	  if (val == 0xFFFF || val <= 0x200)
	  {
	      rvb.StartAddr = rvb.CurrAddr = 0;
	  }
	  else
	  {
	      const s32 iv = (u32) val << 2;
	      if (rvb.StartAddr != iv)
	      {
		  rvb.StartAddr = (u32) val << 2;
		  rvb.CurrAddr = rvb.StartAddr;
	      }
	  }
	  break;
	  //-------------------------------------------------//
