u16 SPUreadRegister(u32 reg)
{
    const u32 r = reg & 0xfff;

    if (r >= 0x0c00 && r < 0x0d80)
    {
	switch (r & 0x0f)
	{
	  case 0xC:		// get adsr vol
	  {
	      const int ch = (r >> 4) - 0xc0;
	      if (s_chan[ch].bNew)
		  return 1;	// we are started, but not processed? return 1
	      if (s_chan[ch].ADSRX.lVolume &&	// same here... we haven't decoded one sample yet, so no envelope yet. return 1 as well
		  !s_chan[ch].ADSRX.EnvelopeVol)
		  return 1;
	      return (u16) (s_chan[ch].ADSRX.EnvelopeVol >> 16);
	  }

	  case 0xE:		// get loop address
	  {
	      const int ch = (r >> 4) - 0xc0;
	      if (s_chan[ch].pLoop == NULL)
		  return 0;
	      return (u16) ((s_chan[ch].pLoop - spuMemC) >> 3);
	  }

return (u16) (s_chan[ch].ADSRX.EnvelopeVol >> 16);
	  }

	  case 0xE:		// get loop address
	  {
	      const int ch = (r >> 4) - 0xc0;
	      if (s_chan[ch].pLoop == NULL)
		  return 0;
	      return (u16) ((s_chan[ch].pLoop - spuMemC) >> 3);
	  }
	}
    }

    switch (r)
    {
      case H_SPUctrl:
	  return spuCtrl;

      case H_SPUstat:
	  return spuStat;

      case H_SPUaddr:
	  return (u16) (spuAddr >> 3);

      case H_SPUdata:
      {
	  u16 s = BFLIP16(spuMem[spuAddr >> 1]);
	  spuAddr += 2;
	  if (spuAddr > 0x7ffff)
	      spuAddr = 0;
	  return s;
      }

      case H_SPUirqAddr:
	  return spuIrq;

	  //case H_SPUIsOn1:
	  // return IsSoundOn(0,16);

	  //case H_SPUIsOn2:
	  // return IsSoundOn(16,24);

    }

    return regArea[(r - 0xc00) >> 1];
}

