////////////////////////////////////////////////////////////////////////
// PITCH register write
////////////////////////////////////////////////////////////////////////

void SetPitch(int ch, u16 val)	// SET PITCH
{
    int NP;
    if (val > 0x3fff)
	NP = 0x3fff;		// get pitch val
    else
	NP = val;

    s_chan[ch].iRawPitch = NP;

    NP = (44100L * NP) / 4096L;	// calc frequency
    if (NP < 1)
	NP = 1;			// some security
    s_chan[ch].iActFreq = NP;	// store frequency
}

