	    double ldiff, rdiff, avg, tmp;

	    avg = ((sl + sr) / 2);
	    ldiff = sl - avg;
	    rdiff = sr - avg;

	    tmp = avg + ldiff * _interpolation_coefficient;
	    if (tmp < -32768)
		tmp = -32768;
	    if (tmp > 32767)
		tmp = 32767;
	    sl = tmp;

	    tmp = avg + rdiff * _interpolation_coefficient;
	    if (tmp < -32768)
		tmp = -32768;
	    if (tmp > 32767)
		tmp = 32767;
	    sr = tmp;
	}

	/* fix dynamic range. */
	sl = (sl * volmul) >> 10;
	sr = (sr * volmul) >> 10;

	if (sl > 32767)
	    sl = 32767;
	if (sl < -32767)
	    sl = -32767;
	if (sr > 32767)
	    sr = 32767;
	if (sr < -32767)
	    sr = -32767;

	*pS++ = sl;
	*pS++ = sr;
    }

    return (1);
}

