	upse_psftag_t *tmp = tags->next;

	free(tags->key);
	free(tags->value);
	free(tags);

	tags = tmp;
    }
}

static void _upse_psf_add_tag(upse_psftag_t ** tag, const char *key, const char *val)
{
    upse_psftag_t *tmp;

    tmp = malloc(sizeof(upse_psftag_t));

tags = tmp;
    }
}

static void _upse_psf_add_tag(upse_psftag_t ** tag, const char *key, const char *val)
{
    upse_psftag_t *tmp;

    tmp = malloc(sizeof(upse_psftag_t));
    memset(tmp, 0, sizeof(upse_psftag_t));

    tmp->key = strdup(key);
    tmp->value = strdup(val);
    tmp->next = NULL;

    if (!*tag)
	*tag = tmp;
    else
    {
	upse_psftag_t *rec;
	rec = *tag;
	while (rec->next)
	    rec = rec->next;
	rec->next = tmp;
    }

}

