static INLINE void doBranch(u32 tar)
{
    u32 tmp;

    branch2 = branch = 1;
    branchPC = tar;

    upse_r3000_cpu_regs.code = BFLIP32(PSXMu32(upse_r3000_cpu_regs.pc));

	if(_upse_breakpoint_callback_f != NULL && upse_r3000_cpu_regs.pc == _upse_breakpoint_address)
	{
		_upse_breakpoint_callback_f(sampcount, _upse_breakpoint_cb_user_data);
	}

    upse_r3000_cpu_regs.pc += 4;

    upse_r3000_cpu_regs.cycle++;

    // check for load delay
    tmp = upse_r3000_cpu_regs.code >> 26;
    switch (tmp)
    {
      case 0x10:		// COP0
	  switch (_Rs_)
	  {
	    case 0x00:		// MFC0
	    case 0x02:		// CFC0
		psxDelayTest(_Rt_, branchPC);
		return;
	  }
	  break;
      case 0x32:		// LWC2
	  psxDelayTest(_Rt_, branchPC);
	  return;
      default:
	  if (tmp >= 0x20 && tmp <= 0x26)
	  {			// LB/LH/LWL/LW/LBU/LHU/LWR
	      psxDelayTest(_Rt_, branchPC);
	      return;
	  }
	  break;
    }

    psxBSC[upse_r3000_cpu_regs.code >> 26] ();

    if ((upse_r3000_cpu_regs.pc - 8) == branchPC && !(upse_r3000_cpu_regs.code >> 26))
    {

psxDelayTest(_Rt_, branchPC);
	      return;
	  }
	  break;
    }

    psxBSC[upse_r3000_cpu_regs.code >> 26] ();

    if ((upse_r3000_cpu_regs.pc - 8) == branchPC && !(upse_r3000_cpu_regs.code >> 26))
    {
	//printf("%08x\n",upse_r3000_cpu_regs.code>>26);
	CounterDeadLoopSkip();
    }
    branch = 0;
    upse_r3000_cpu_regs.pc = branchPC;

    psxBranchTest();
}

