    channel->update_flags &= ~AKAO_UPDATE_ALTERNATIVE;

    channel->attr.rr = g_akao_instrument[channel->intsr_id].rr;
    channel->attr.mask |= SPU_VOICE_ADSR_RMODE | SPU_VOICE_ADSR_RR;
}



