        {
            V1 += 1;
            if( V1 >= 0xf01 )
            {
                A0 = 0x800104fc; // "SPU:T/O [%s]"
                A1 = 0x8001050c; // "wait (IRQ/ON)"
                system_bios_printf();

                return SPU_ERROR;
