    IR1 = cos_y;
    IR2 = 0;
    IR3 = -sin_y;
    gte_gpl12(); // General purpose interpolation

    IR1 = (MAC1 >> c) & ffff; // cos_z * T1 - sin_z * cos_y
    IR2 = (MAC2 >> c) & ffff; // cos_z * cos_x
    IR3 = (MAC3 >> c) & ffff; // cos_z * T2 + sin_z * sin_y
    gte_rtir12(); // ir * rotmatrix
    [1f800024] = h(IR1);
    [1f80002a] = h(IR2);
    [1f800030] = h(IR3);
