    switch (bank)
    {
        case 0x0:
        {
            u8 value = bu[events_data + script_cur + ofs];
            if (g_field_debug_flags & 0x3) field_debug_add_parse_value_to_page2("G cons=", value, 0x2);
            return value;

case 0x6: bank = bu[events_data + script_cur + 0x3] & 0xf; break;
    }

