def find_opcode(fd, opcode_name: str) -> list[str]:
    out: list[str] = []
    for slot in fd.scripts:
        pos = 0
        for raw, name in decode_ops(slot.raw):
            if name == opcode_name or name.startswith(opcode_name + "."):
                abs_off = slot.start + pos
                out.append(
